Method.Source:
/// <summary>
///     AVA <c>updateOrderAfterCancelingDeliveryRemainder</c> method.
///     Updates the sales order after cancelling the delivery remainder on the sales order lines.
///     AVA - Schneider 20.02.2024
/// </summary>
/// <param name="_salesTable">
///     <c>SalesTable</c> as type
/// </param>
/// <param name="_mcrSalesOrderCancellation">
///     <c>MCRSalesOrderCancellation</c> as type
/// </param>
protected void updateOrderAfterCancelingDeliveryRemainder(SalesTable _salesTable, MCRSalesOrderCancellation _mcrSalesOrderCancellation)
{
    SalesTable locSalesTable;

    locSalesTable = _salesTable;
    /* moved to cancelMultipleOrdersDeliveryRemainder before processing the sales table just change sales status
    if(     locSalesTable.SalesType     == SalesType::Journal           // Journal
        &&  locSalesTable.SalesStatus   == SalesStatus::BacKOrder   )   // Offener Auftrag
    {
        locSalesTable.avaUpdateAlterJournalSalesStatus();
    }
    */

    next updateOrderAfterCancelingDeliveryRemainder(locSalesTable, _mcrSalesOrderCancellation);
}

/// <summary>
///     AVA <c>cancelMultipleOrdersDeliveryRemainder</c> method.
///     Loops over many Sales Orders invoking <c>cancelOpenOrderLinesDeliveryRemainder</c> method on them.
///     AVA - Schneider 20.02.2024
/// </summary>
/// <param name="_salesRecIdList">
///     <c>List</c> as type
/// </param>
/// <remarks>
///     This operation is not atomic.
/// </remarks>
public void cancelMultipleOrdersDeliveryRemainder(List _salesRecIdList)
{
    List            locSalesTableRecList;
    ListEnumerator  locListEnumerator;
    SalesTable      locSalesTable;
    RecId           locSalesTableRecId;

    locSalesTableRecList = new List(Types::Int64);

    locListEnumerator = _salesRecIdList.getEnumerator();

    while (locListEnumerator.moveNext())
    {
        locSalesTableRecId  = locListEnumerator.current();
        locSalesTable       = SalesTable::findRecId(locSalesTableRecId);
        if(     locSalesTable.SalesType     == SalesType::Journal           // Journal
            &&  locSalesTable.SalesStatus   == SalesStatus::BacKOrder   )   // Offener Auftrag
        {
            locSalesTable.avaUpdateAlterJournalSalesStatus();
        }
        else if(    locSalesTable.SalesType     == SalesType::Journal       // Journal
                &&  locSalesTable.SalesStatus   == SalesStatus::Canceled)   // Strorniert
        {
            locSalesTable.avaUpdateAlterJournalSalesStatus();
        }
        else
        {
            locSalesTableRecList.addEnd(locSalesTableRecId);
        }
    }

    next cancelMultipleOrdersDeliveryRemainder(locSalesTableRecList);
}
